{
  "action": "final",
  "output": {
    "research_concepts": [
      "play-type labeling",
      "AVOID labels",
      "opponent next-possession PPP",
      "own-sequence lags",
      "play-type data quality",
      "points per possession after play",
      "defensive aftermath of offensive actions"
    ],
    "methodological_questions": [
      "How to define and align opponent next-possession after a specific play type?",
      "How to handle end-of-period possessions when next opponent possession may not exist?",
      "What is the sample size and exposure sparsity for individual play types?",
      "What threshold effect size is 'large enough' to assign an AVOID label?",
      "How to incorporate own-sequence lags (prior/subsequent own possessions) in labeling?",
      "What confounding factors (score, time, opponent strength) affect opponent next-possession PPP?",
      "Risk of lookahead bias when using outcome data to label past plays?",
      "Reliability and precision of points-per-possession metrics per play type?",
      "Statistical power to detect meaningful differences in opponent PPP across play types?"
    ],
    "historical_evidence": [
      {
        "id": "FAM:SF-APPS-075",
        "status_as_recorded": "not a hypothesis test",
        "finding": "4/8 PTs downstream real: CUT Ext 1.658 (supp +0.0220), TRANSITION 1.509 (+0.0145), SPOT_UP 1.303 (+0.0124), POST_UP 1.127 (+0.0194). DRIVE downstream not real (opp ATT +0.0024). Player downstream mostly BH ns except M. M. Downstream effects are small (~0.01-0.02 PPP) relative to direct PPP gaps."
      },
      {
        "id": "FAM:SF-CHT-029",
        "status_as_recorded": "artifact",
        "finding": "FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0."
      },
      {
        "id": "FAM:SF-APPM-014",
        "status_as_recorded": "not a hypothesis test",
        "finding": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail. Play type labels have systematic issues that undermine adaptation findings."
      },
      {
        "id": "FAM:SF-CHT-025",
        "status_as_recorded": "artifact",
        "finding": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type."
      },
      {
        "id": "FAM:SF-PAP-096",
        "status_as_recorded": "artifact",
        "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20"
      }
    ],
    "failed_approaches": [
      {
        "id": "FAM:SF-CHT-029",
        "what_failed": "Attempt to detect decaying cross-possession memory of play-type actions",
        "why": "Flat lifts collapsed under within-team baseline; team-quality confound."
      },
      {
        "id": "FAM:SF-APPM-014",
        "what_failed": "Play-type label accuracy audit",
        "why": "Label systematic issues: high OTHER%, low confidence, foul leakage, team identity failures."
      },
      {
        "id": "FAM:SF-CHT-025",
        "what_failed": "Play-type labeling audit: foul leakage and initiation_type mapping",
        "why": "OTHER inflated by 36% foul endings; DRIVE 12pp below foul benchmark; only 0.7% map via initiation_type."
      },
      {
        "id": "FAM:SF-PAP-096",
        "what_failed": "Play-type classifier assisted-flag leak",
        "why": "SPOT_UP 2.83 PPP because assisted flag only on makes; leak poisoned simulation."
      }
    ],
    "evidence_establishes": [
      "Opponent next-possession PPP after a play type shows very small effects (~0.01-0.02 PPP) for some play types (SF-APPS-075).",
      "Cross-possession carryover effects of play types are flat and confounded by team quality; no reliable decay pattern (SF-CHT-029).",
      "Current inferred play-type labels have systematic errors: high OTHER%, foul leakage, low confidence, and a documented assisted-flag leak that inflates PPP (SF-APPM-014, SF-CHT-025, SF-PAP-096)."
    ],
    "evidence_does_not_establish": [
      "Magnitude of opponent T+1 effects after fully corrected play-type labels.",
      "Whether own-sequence lag effects exist after adequate confounding control.",
      "What precise effect-size threshold would be considered 'large enough' for AVOID labels.",
      "The statistical power to detect small effects for rare play types in current data."
    ],
    "own_inferences": [
      "Even after label corrections, opponent next-possession PPP differences are likely too small (<0.03 PPP) to drive an actionable AVOID label system, unless a very sensitive threshold is adopted.",
      "Confounding by team quality and game context is likely to persist even with within-team adjustments, making causal attribution difficult.",
      "The AVOID label derivation itself risks circularity (OUTCOME_DERIVED_LABEL) and lookahead bias if not carefully split temporally.",
      "A minimal viable test would require redesigned play-type inference, explicit temporal holdout, and a pre-registered effect-size threshold."
    ],
    "uncertainties": [
      "Size of opponent T+1 effects after fully corrected labels (post-rewrite, post-fix) is unknown but likely still small.",
      "Stakeholder-defined threshold for 'large enough' is unspecified; without it, the decision rule is arbitrary.",
      "Sample size per play type for reliable PPP estimation may still be insufficient for the rarest play types.",
      "Interaction between opponent next-PPP and own-sequence lags not explored in prior work; could introduce additional complexity."
    ],
    "historical_effect": {
      "changed_decision": "yes",
      "explanation": "Without historical evidence, one might assume that opponent next-possession PPP after a play type can be cleanly measured and that effects might be of practical size. The evidence shows that prior work found small, confounded effects and that the underlying play-type labels are unreliable, making a successful test unlikely without substantial methodological fixes."
    },
    "testability": {
      "p_testable": 0.15,
      "blocking_constraints": [
        {
          "code": "LABEL_ERROR",
          "text": "Play-type labels have documented systematic errors (high OTHER%, foul leakage, assisted-flag leak) that bias PPP estimates."
        },
        {
          "code": "CONFOUNDING",
          "text": "Opponent next-possession PPP is confounded by team quality, score, game context; within-team adjustments may not fully remove."
        },
        {
          "code": "SAMPLE_SIZE_POWER",
          "text": "Prior effect estimates ~0.01-0.02 PPP; detecting such small effects requires tens of thousands of possessions per play type. Rare play types likely underpowered."
        },
        {
          "code": "LEAKAGE_LOOKAHEAD",
          "text": "If AVOID labels are derived from the same data without temporal separation, future information can leak into the labeling."
        },
        {
          "code": "OUTCOME_DERIVED_LABEL",
          "text": "AVOID labels are defined by the outcome itself, creating circularity if not validated on independent data."
        }
      ]
    },
    "prior_work": {
      "already_answered": "partly",
      "cited": [
        "FAM:SF-APPS-075",
        "FAM:SF-CHT-029",
        "FAM:SF-APPM-014",
        "FAM:SF-CHT-025",
        "FAM:SF-PAP-096"
      ],
      "summary": "Prior work partially addresses the question: SF-APPS-075 measured opponent next-PPP suppression and found small effects; SF-CHT-029 tested cross-possession memory and found flat, confounded lifts. However, the specific decision rule for AVOID labels and the combined consideration of own-sequence lags have not been directly tested. Multiple artifacts in play-type labeling complicate any direct follow-up."
    },
    "risks": [
      {
        "code": "LABEL_ERROR",
        "text": "Play-type labels contain systematic errors (OTHER%, foul leakage, assisted-flag leak) that bias per-PT PPP metrics."
      },
      {
        "code": "CONFOUNDING",
        "text": "Differences in opponent next-PPP across play types may reflect team quality, game situation, and lineup strength rather than a causal effect of the play type."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Effect sizes (~0.01-0.02 PPP) require very large n per play type; the rarest play types (e.g., lob, off-screen) may have insufficient possessions."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "If AVOID labels are determined using outcomes from the same season without proper temporal holdout, future information can contaminate the labeling."
      },
      {
        "code": "OUTCOME_DERIVED_LABEL",
        "text": "The AVOID label is constructed from opponent next-PPP, which is the same outcome used to validate the label, creating circularity unless an independent sample is used."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "Testing many play types and two outcome directions inflates false positive risk."
      },
      {
        "code": "MECHANICAL_FLOOR",
        "text": "End-of-quarter/game possessions lack a subsequent opponent possession, introducing selection if not handled."
      },
      {
        "code": "RTM_SELECTION",
        "text": "Selecting play types with extreme opponent next-PPP values may lead to regression toward the mean on reassessment."
      }
    ],
    "predicted_outcome": {
      "supported": 0.05,
      "rejected": 0.05,
      "untestable": 0.35,
      "artifact": 0.35,
      "uncertain": 0.20
    },
    "decision": "do_not_proceed",
    "design": {
      "estimand": "The causal effect of running play type X on (a) points per possession in the immediately following opponent possession, and (b) points per possession in the immediately following own-team possession, relative to the average after all other play types, adjusted for confounders.",
      "unit": "Offensive possession that ends and is followed by at least one opponent possession within the same game period.",
      "sample": "All NBA possessions from 2022-23 through 2025-26 regular season and playoffs, excluding end-of-period/game possessions without a subsequent opponent possession. Use only possessions labeled with high-confidence play types after all documented label fixes (post-rewrite, post-fix).",
      "power": "Assuming true effect sizes of ~0.01-0.02 PPP, detecting a difference of 0.015 PPP at 80% power requires ~50,000 possessions per play type. Common play types (PNR, spot-up, drive) exceed this; rare types (lob, off-screen) likely fall short. Power analysis must be updated after label quality assessment.",
      "controls": "Score differential, time remaining in quarter, opponent season defensive rating, home/away, rest days, possession start type (made/miss/FT/turnover), team fixed effects (for opponent outcome) and team+opponent fixed effects (for own outcome). Own-sequence lags additionally control for own offensive rating.",
      "falsification": "Placebo tests: opponent PPP on the second following possession (T+2) where no direct effect is plausible; own PPP on the possession two steps ahead. Sanity checks for label artifacts: verify PPP distributions do not exceed feasible ranges and that assisted-flag leak is absent.",
      "multiplicity": "Bonferroni correction across all tested play types (8-12) and two outcomes. Complement with Bayesian hierarchical model reporting posterior probabilities with skeptical priors.",
      "decision_rule": "A play type X receives an AVOID label if: (a) the adjusted posterior probability that its opponent next-PPP effect exceeds +0.03 PPP is >0.95 in a training sample (e.g., 2022-23 through 2024-25), and (b) the effect replicates in the holdout season(s) (2025-26) with directionally consistent point estimate and p<0.05 after correction. Analogous rule for own-sequence lag effects.",
      "data_version": "NBA 2022-23 through 2025-26, using corrected play-type labels from the graph database built from play-by-play, with all patches to play_type_inferrer.py applied as of 2026-06-19."
    }
  }
}

